<template><div v-if="item" class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">{{ item.title }}</h1><div class="m-card text-sm text-slate-600"><p>{{ item.description || 'No description' }}</p><p class="mt-2 text-xs text-slate-400">{{ item.status }}</p></div><NuxtLink :to="`/supplier/make-offer?request_id=${item.id}`" class="m-btn-primary block text-center">Submit offer</NuxtLink></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const route=useRoute();const {listSupplierPings}=useCommerce();const item=ref<any>();onMounted(async()=>item.value=(await listSupplierPings()).items.find((x:any)=>x.id===String(route.params.id)))</script>
